## Real-World Example: Searchable Product Catalog

Let’s build a component that:

- Fetches products with pagination
- Supports search and filtering
- Caches results
- Handles loading and errors
- Implements optimistic search

```jsx
import { useState, useRef } from 'react';
import axios from 'axios';

function ProductCatalog() {
  const [query, setQuery] = useState('');
  const [page, setPage] = useState(1);
  const [products, setProducts] = useState([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);
  const cache = useRef({});

  const fetchProducts = async (q = query, p = page) => {
    const cacheKey = `${q}:${p}`;
    if (cache.current[cacheKey]) {
      setProducts(cache.current[cacheKey]);
      return;
    }

    setLoading(true);
    setError(null);
    try {
      const res = await axios.get('https://api.example.com/products', {
        params: { q, page: p, limit: 10 },
      });
      cache.current[cacheKey] = res.data;
      setProducts(res.data);
    } catch (err) {
      setError(err.message);
    } finally {
      setLoading(false);
    }
  };

  // Debounce search
  const debouncedFetch = useRef(
    debounce((q) => fetchProducts(q, 1), 500)
  ).current;

  useEffect(() => {
    debouncedFetch(query);
  }, [query]);

  useEffect(() => {
    fetchProducts();
  }, [page]);

  return (
    <div>
      <input
        type="text"
        placeholder="Search products..."
        value={query}
        onChange={(e) => setQuery(e.target.value)}
      />

      {loading && <div>Loading...</div>}
      {error && <div style={{ color: 'red' }}>{error}</div>}

      <ul>
        {products.map((p) => (
          <li key={p.id}>{p.name} - ${p.price}</li>
        ))}
      </ul>

      <div>
        <button onClick={() => setPage(p => Math.max(1, p - 1))}>Previous</button>
        <span>Page {page}</span>
        <button onClick={() => setPage(p => p + 1)}>Next</button>
      </div>
    </div>
  );
}

// Simple debounce utility
function debounce(fn, delay) {
  let timeout;
  return (...args) => {
    clearTimeout(timeout);
    timeout = setTimeout(() => fn(...args), delay);
  };
}
```

> 🔁 **Optimization Note**: This avoids refetching on every keystroke by debouncing the search input.

