## Custom Hooks for Data Fetching

Duplicating fetch logic across components is error-prone. Abstract it into a reusable hook.

### `useFetch` Hook

```jsx
import { useState, useEffect, useRef } from 'react';
import axios from 'axios';

export function useFetch(url, options = {}) {
  const [data, setData] = useState(null);
  const [error, setError] = useState(null);
  const [loading, setLoading] = useState(false);
  const cache = useRef({});
  const controllerRef = useRef(null);

  const fetchData = async () => {
    // Cancel previous request
    if (controllerRef.current) {
      controllerRef.current.abort();
    }

    const controller = new AbortController();
    controllerRef.current = controller;
    setLoading(true);
    setError(null);

    try {
      const cacheKey = url + (options.params ? JSON.stringify(options.params) : '');
      if (cache.current[cacheKey]) {
        setData(cache.current[cacheKey]);
        return;
      }

      const response = await axios.get(url, {
        ...options,
        signal: controller.signal,
      });

      cache.current[cacheKey] = response.data;
      setData(response.data);
    } catch (err) {
      if (!axios.isCancel(err)) {
        setError(err.message);
      }
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchData();
    return () => {
      controllerRef.current?.abort();
    };
  }, [url, JSON.stringify(options.params)]);

  return { data, error, loading, refetch: fetchData };
}
```

> 🔁 **Usage**:
> ```jsx
> function ProductGrid() {
>   const { data: products, loading, error } = useFetch('https://api.example.com/products');
>   // ...
> }
> ```

> 💡 This hook supports:
> - Caching by URL + params
> - Request cancellation
> - Manual refetch via returned `refetch`
> - Automatic cleanup

