## Middleware and Advanced Patterns

Toolkit ships with sensible defaults, but you can extend behavior with custom middleware.

### Example: Adding a logger for development

```javascript
import { configureStore } from '@reduxjs/toolkit';
import logger from 'redux-logger';
import { apiSlice } from '../features/api/apiSlice';
import tasksReducer from '../features/tasks/tasksSlice';

const store = configureStore({
  reducer: {
    tasks: tasksReducer,
    [apiSlice.reducerPath]: apiSlice.reducer,
  },
  middleware: getDefaultMiddleware =>
    getDefaultMiddleware()
      .concat(apiSlice.middleware)
      .concat(logger), // dev-only
});
```

### Conditional middleware

Only include `logger` in development:

```javascript
const middlewares = [apiSlice.middleware];
if (import.meta.env.DEV) middlewares.push(logger);

const store = configureStore({ reducer, middleware: middlewares });
```

### Persistence with redux-persist

Install:

```bash
npm install redux-persist
```

Configure:

```javascript
import { persistStore, persistReducer } from 'redux-persist';
import storage from 'redux-persist/lib/storage';

const persistConfig = {
  key: 'root',
  storage,
  blacklist: [apiSlice.reducerPath], // don't persist cache
};

const persistedReducer = persistReducer(persistConfig, rootReducer);

export const store = configureStore({
  reducer: persistedReducer,
  middleware: getDefaultMiddleware =>
    getDefaultMiddleware({
      serializableCheck: {
        ignoredActions: ['persist/PERSIST'], // ignore redux-persist actions
      },
    }).concat(apiSlice.middleware),
});

export const persistor = persistStore(store);
```

Wrap your app:

```javascript
import { PersistGate } from 'redux-persist/integration/react';

ReactDOM.createRoot(root).render(
  <Provider store={store}>
    <PersistGate loading={null} persistor={persistor}>
      <App />
    </PersistGate>
  </Provider>
);
```

